-- supabase/seed.sql — dati DIMOSTRATIVI per il Supabase LOCALE (supabase db reset li applica).
-- Generato da scripts/orc-demo.py: non modificare a mano, rigenerare. Tutto inventato.
-- Mai in produzione: là il roster si carica dalla pagina Musicisti → Importa (orchestre/demo/musicisti-demo.csv).

-- utente demo (password: Prova-1234!) — solo locale
insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
  raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token, email_change_token_new, email_change)
values ('00000000-0000-0000-0000-000000000000', '00000000-0000-4000-8000-00000000d3a0', 'authenticated', 'authenticated', 'demo@example.invalid',
  crypt('Prova-1234!', gen_salt('bf')), now(), '{"provider":"email","providers":["email"]}', '{"full_name":"Demo Orchestre"}', now(), now(), '', '', '', '')
on conflict (id) do nothing;
insert into auth.identities (id, user_id, provider_id, provider, identity_data, created_at, updated_at, last_sign_in_at)
values ('00000000-0000-4000-8000-00000000d3a0', '00000000-0000-4000-8000-00000000d3a0', '00000000-0000-4000-8000-00000000d3a0', 'email',
  '{"sub":"00000000-0000-4000-8000-00000000d3a0","email":"demo@example.invalid","email_verified":true}', now(), now(), now())
on conflict (provider_id, provider) do nothing;

insert into public.orc_profiles (id, display_name) values ('00000000-0000-4000-8000-00000000d3a0', 'Demo Orchestre') on conflict do nothing;
insert into public.orc_organizations (id, name, slug, created_by) values ('00000000-0000-4000-8000-00000000d3a1', 'Orchestra Demo', 'orchestra-demo', '00000000-0000-4000-8000-00000000d3a0') on conflict do nothing;
insert into public.orc_memberships (org_id, user_id, role) values ('00000000-0000-4000-8000-00000000d3a1', '00000000-0000-4000-8000-00000000d3a0', 'owner') on conflict do nothing;

-- roster: passa dalla stessa RPC dell'import, così il seed prova anche quella
